+// Export createLocalKv(filePath)
+// Node ESM, standard library only
+// Return frozen API {get, set, delete, has, list, clear}
+// Keys must be non-empty strings; values must be JSON-serializable
+// State file is a JSON object. Missing file means empty store.
+// Existing malformed JSON, non-object, or array must fail closed with Error code/state message STATE_CORRUPT
+// set/delete/clear persist atomically using same-directory temp file then rename
+// create parent directory if needed
+// get returns stored value or undefined; has boolean
+// list returns a new plain object with keys sorted lexicographically
+// No secrets/network/dependencies
+// Never write until a mutation method is called
+// Touch no other file
+// Keep implementation compact and deterministic
+
+import { promises as fs } from 'fs';
+import { join, mkdir, exists } from 'path';
+
+export function createLocalKv(filePath) {
+  const store = new Map();
+
+  async function get(key) {
+    if (typeof key !== 'string' || key.length === 0) {
+      throw new TypeError('Key must be a non-empty string');
+    }
+    return store.get(key);
+  }
+
+  async function set(key, value) {
+    if (typeof key !== 'string' || key.length === 0) {
+      throw new TypeError('Key must be a non-empty string');
+    }
+    if (typeof value === 'undefined' || typeof value === 'function' || typeof value === 'symbol' || typeof value === 'bigint') {
+      throw new TypeError('Value must be JSON-serializable');
+    }
+
+    const tempFilePath = join(filePath, '.tmp');
+    const dirPath = join(filePath, '..');
+
+    try {
+      await mkdir(dirPath, { recursive: true });
+      const data = JSON.stringify(Object.fromEntries(store));
+      await fs.writeFile(tempFilePath, data);
+      await fs.rename(tempFilePath, filePath);
+    } catch (error) {
+      if (error.code === 'ENOENT') {
+        await mkdir(dirPath, { recursive: true });
+        await fs.writeFile(tempFilePath, JSON.stringify(Object.fromEntries(store)));
+        await fs.rename(tempFilePath, filePath);
+      } else {
+        throw error;
+      }
+    }
+
+    store.set(key, value);
+  }
+
+  async function delete(key) {
+    if (typeof key !== 'string' || key.length === 0) {
+      throw new TypeError('Key must be a non-empty string');
+    }
+
+    const tempFilePath = join(filePath, '.tmp');
+    const dirPath = join(filePath, '..');
+
+    try {
+      await mkdir(dirPath, { recursive: true });
+      const data = JSON.stringify(Object.fromEntries(store));
+      await fs.writeFile(tempFilePath, data);
+      await fs.rename(tempFilePath, filePath);
+    } catch (error) {
+      if (error.code === 'ENOENT') {
+        await mkdir(dirPath, { recursive: true });
+        await fs.writeFile(tempFilePath, JSON.stringify(Object.fromEntries(store)));
+        await fs.rename(tempFilePath, filePath);
+      } else {
+        throw error;
+      }
+    }
+
+    store.delete(key);
+  }
+
+  async function has(key) {
+    if (typeof key !== 'string' || key.length === 0) {
+      throw new TypeError('Key must be a non-empty string');
+    }
+    return store.has(key);
+  }
+
+  async function list() {
+    const keys = Array.from(store.keys()).sort();
+    const result = {};
+    for (const key of keys) {
+      result[key] = store.get(key);
+    }
+    return result;
+  }
+
+  async function clear() {
+    const tempFilePath = join(filePath, '.tmp');
+    const dirPath = join(filePath, '..');
+
+    try {
+      await mkdir(dirPath, { recursive: true });
+      await fs.writeFile(tempFilePath, '{}');
+      await fs.rename(tempFilePath, filePath);
+    } catch (error) {
+      if (error.code === 'ENOENT') {
+        await mkdir(dirPath, { recursive: true });
+        await fs.writeFile(tempFilePath, '{}');
+        await fs.rename(tempFilePath, filePath);
+      } else {
+        throw error;
+      }
+    }
+
+    store.clear();
+  }
+
+  return Object.freeze({ get, set, delete: delete, has, list, clear });
+}

